// Exercise library: ExerciseDB v1 text data (MIT, see NOTICE.md) + Chinese names + movement pattern mapping.
// Generated by scripts/build-exercises.mjs into src/data/exercises.json and loaded dynamically on demand (separate lazy chunk, not in the main bundle).

import type { ExerciseInfo, PatternId } from './movement/types'

// ------------------------------------------------------------------ Loading

let cache: Promise<ExerciseInfo[]> | null = null
let byId: Map<string, ExerciseInfo> | null = null

/** Load the full exercise library (loaded once, then the same Promise is reused) */
export function loadExercises(): Promise<ExerciseInfo[]> {
  if (!cache) {
    cache = import('../data/exercises.json')
      .then((m) => {
        const list = m.default as unknown as ExerciseInfo[]
        byId = new Map(list.map((e) => [e.id, e]))
        return list
      })
      .catch((err) => {
        cache = null // Allow retry after failures such as network hiccups
        throw err
      })
  }
  return cache
}

/** Get an exercise by id (loading the library first if needed) */
export async function getExercise(id: string): Promise<ExerciseInfo | undefined> {
  if (!byId) await loadExercises()
  return byId!.get(id)
}

/** Synchronous lookup: works once the library is loaded, returns undefined otherwise */
export function peekExercise(id: string): ExerciseInfo | undefined {
  return byId?.get(id)
}

