// ------------------------------------------------------------------ Search

export interface ExerciseFilter {
  bodyPart?: string
  equipment?: string
  pattern?: PatternId
  /** Only video-analyzable ones (non-null pattern) */
  analyzableOnly?: boolean
}

/** Common abbreviations / nicknames → expanded into alternatives where any match counts */
const ALIASES: Record<string, string[]> = {
  rdl: ['romanian deadlift'],
  sldl: ['stiff leg deadlift', 'straight leg deadlift'],
  ohp: ['overhead press', 'military press', 'shoulder press'],
  bss: ['split squat'],
  pullup: ['pull-up', 'pull up'],
  chinup: ['chin-up'],
  pushup: ['push-up', 'push up'],
  situp: ['sit-up', 'sit up'],
  stepup: ['step-up', 'step up'],
  latpulldown: ['pulldown'],
  保加利亚: ['分腿蹲'],
  二头: ['弯举'],
  三头: ['臂屈伸', '下压', '后踢', '法式推举'],
  龙门架: ['绳索'],
  拉力器: ['绳索'],
  腿举: ['倒蹬', '腿举'],
  倒蹬: ['倒蹬', '腿举'],
  肩推: ['肩推', '推举'],
  推肩: ['肩推', '推举'],
  夹胸: ['夹胸', '飞鸟'],
  蝴蝶机: ['器械坐姿夹胸'],
  腹肌: ['卷腹', '仰卧起坐', '举腿'],
  平板: ['平板支撑'],
  罗马尼亚: ['罗马尼亚硬拉'],
  高位下拉: ['高位下拉', '下拉'],
  后蹲: ['杠铃深蹲', '高杠深蹲', '低杠深蹲'],
  深蹲: ['深蹲', '全蹲', '前蹲'],
}

const norm = (s: string) => s.toLowerCase().replace(/[‐-―]/g, '-').replace(/\s+/g, ' ').trim()
/** Strip spaces, hyphens and punctuation so pullup / pull-up / pull up all find each other */
const compact = (s: string) => norm(s).replace(/[\s\-_.,·'’()（）/]+/g, '')

interface Indexed {
  e: ExerciseInfo
  zh: string
  name: string
  nameC: string
  words: string[]
  /** Chinese/English labels for equipment/body part/muscle group; a hit counts as a weak match */
  tags: string
}

const indexCache = new WeakMap<ExerciseInfo[], Indexed[]>()
function indexOf(list: ExerciseInfo[]): Indexed[] {
  let idx = indexCache.get(list)
  if (!idx) {
    idx = list.map((e) => {
      const name = norm(e.name)
      return {
        e,
        zh: e.zh,
        name,
        nameC: compact(e.name),
        words: name.split(/[\s\-()/,]+/).filter(Boolean),
        tags: [e.bodyPart, e.equipment, e.target, bodyPartZh(e.bodyPart), equipmentZh(e.equipment), muscleZh(e.target)].join(' ').toLowerCase(),
      }
    })
    indexCache.set(list, idx)
  }
  return idx
}

/** Match score of a single term against one exercise (0 = no match) */
function termScore(x: Indexed, term: string): number {
  const alts = [term, ...(ALIASES[term] ?? ALIASES[compact(term)] ?? [])]
  let best = 0
  for (const t of alts) {
    const tc = compact(t)
    if (!tc) continue
    let s = 0
    if (x.zh === t) s = 1000
    else if (x.name === t || x.nameC === tc) s = 950
    else if (x.zh.endsWith(t)) s = 640 // Chinese exercise names put the head term last: 杠铃「卧推」, 哑铃「弯举」
    else if (x.zh.startsWith(t)) s = 560
    else if (x.zh.includes(t)) s = 520 - Math.min(x.zh.indexOf(t), 20) * 4
    else if (x.name.startsWith(t)) s = 600
    else if (x.words.some((w) => w === t)) s = 480
    else if (x.words.some((w) => w.startsWith(t))) s = 420
    else if (x.name.includes(t)) s = 300
    else if (tc.length >= 4 && x.nameC.includes(tc)) s = 260
    else if (x.tags.includes(t)) s = 120
    if (t !== term) s = Math.round(s * 0.9) // Alias hits score slightly below the original term
    if (s > best) best = s
  }
  return best
}

/**
 * Search the exercise library: Chinese / English / partial words / common abbreviations (rdl, ohp…); all terms must match.
 * Ranking: exact > prefix > Chinese substring > English word > substring > tag; ties favor big three, video-analyzable, shorter names.
 * With an empty query only filter, ordered big three → common → video-analyzable → Chinese name.
 */
export function searchExercises(list: ExerciseInfo[], query: string, filter: ExerciseFilter = {}): ExerciseInfo[] {
  const { bodyPart, equipment, pattern, analyzableOnly } = filter
  const pass = (e: ExerciseInfo) =>
    (!bodyPart || e.bodyPart === bodyPart) &&
    (!equipment || e.equipment === equipment) &&
    (!pattern || e.pattern === pattern) &&
    (!analyzableOnly || e.pattern !== null)

  const q = norm(query)
  const idx = indexOf(list)
  if (!q) {
    const rank = (e: ExerciseInfo) => (e.big3 ? 0 : COMMON_RANK.has(e.id) ? 1 + COMMON_RANK.get(e.id)! / 100 : e.pattern ? 2 : 3)
    return idx
      .filter((x) => pass(x.e))
      .sort((a, b) => rank(a.e) - rank(b.e) || a.zh.length - b.zh.length || a.zh.localeCompare(b.zh, 'zh'))
      .map((x) => x.e)
  }

  // Chinese search works without space tokenization: both 「哑铃 卧推」 and 「哑铃卧推」 match
  const terms = q.split(' ').filter(Boolean)
  const scored: { x: Indexed; s: number }[] = []
  for (const x of idx) {
    if (!pass(x.e)) continue
    let total = 0
    let ok = true
    for (const t of terms) {
      const s = termScore(x, t)
      if (!s) {
        ok = false
        break
      }
      total += s
    }
    // Score the whole query once more (with multiple terms, "barbell bench" matching as a whole prefix is more relevant)
    if (!ok) continue
    if (terms.length > 1) total += termScore(x, q) * 0.5
    if (x.e.big3) total += 200
    if (x.e.pattern) total += 15
    if (COMMON_RANK.has(x.e.id)) total += 60
    total -= Math.min(x.zh.length, 20) // Shorter name = more "basic"
    scored.push({ x, s: total })
  }
  scored.sort((a, b) => b.s - a.s || a.x.zh.localeCompare(b.x.zh, 'zh'))
  return scored.map((r) => r.x.e)
}
